const censusEquals = (
  left: StructuralSchemaCensusV1,
  right: StructuralSchemaCensusV1
): boolean =>
  (Object.keys(right) as (keyof StructuralSchemaCensusV1)[]).every(
    (key) => left[key] === right[key]
  );
const censusDifferences = (
  actual: StructuralSchemaCensusV1,
  expected: StructuralSchemaCensusV1
): string =>
  (Object.keys(expected) as (keyof StructuralSchemaCensusV1)[])
    .filter((key) => actual[key] !== expected[key])
    .map((key) => `${key}:${actual[key]}!=${expected[key]}`)
    .join(",");
